  values ('ME', 'short_answer', 'What is a chatbot? Give a few examples and discuss its advantages and disadvantages. (5 marks)', 'A chatbot is a computer program that conducts a conversation with people through text or voice, either following fixed rules or using artificial intelligence and natural language processing. Examples: ChatGPT and Gemini, voice assistants like Siri and Alexa, and customer-service bots on bank, telecom and airline websites. Advantages: available 24/7; instant answers; can serve many users at once; reduces staff costs; gives consistent information. Disadvantages: may misunderstand complex or local-language questions; can give wrong or invented answers; lacks human empathy; raises privacy and data-security concerns; may replace some jobs.', null, '[{"point": "Definition: software that simulates conversation with users through text or voice, rule-based or AI/NLP-based", "marks": 1}, {"point": "Examples: ChatGPT, Siri, Alexa, bank / telecom customer-service bots", "marks": 1}, {"point": "Advantages: 24/7 service, instant replies, handles many users, lower cost, consistent answers", "marks": 1.5}, {"point": "Disadvantages: limited understanding, wrong or made-up answers, no empathy, privacy/security risks, job loss", "marks": 1.5}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'ict-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 5,
