  values ('ME', 'short_answer', 'You have just joined the office and you receive an email claiming to be from IT asking for your password to be entered in a shared link to resolve an urgent issue. Describe how you would identify whether it is a phishing email and prevent risks. (3 marks)', 'Signs of phishing: genuine IT staff never ask for your password; the message creates false urgency; the sender''s address or the link''s real domain (seen by hovering) does not match the organisation; there may be spelling mistakes or a generic greeting. Response: do not click the link or reply; check with the IT department using a known phone number or in person; report the e-mail to IT/security and delete it. Prevention: use multi-factor authentication, change the password immediately if it was entered, keep spam filters on and attend security-awareness training.', null, '[{"point": "Warning signs: asks for password (IT never does), urgency/threat, suspicious sender address or link (hover to check domain), spelling errors", "marks": 1.5}, {"point": "Do not click or reply; verify with IT through a known phone/channel; report to IT/security and delete", "marks": 1}, {"point": "Prevention: MFA, change password if entered, security awareness training, spam filters", "marks": 0.5}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
